// DeleteUniqueIndexCache 删除索引存在的缓存
func (u *UserBindStudentRepo) DeleteIndexCache(ctx context.Context, data ...*yanxue_model.UserBindStudent) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, u.cache.Key(CacheUserBindStudentByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[u.cache.Key(CacheUserBindStudentByIDPrefix, item.ID)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserBindStudentByUserIDStudentNamePrefix, item.UserID, item.StudentName)] = struct{}{}
			KeyMap[u.cache.Key(CacheUserBindStudentByUserIDPrefix, item.UserID)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := u.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
